/**
 * Place and county reference points from the U.S. Census Gazetteer files
 * (public domain). Used to place projects that have no coordinates.
 *
 * pipeline/data/gazetteer.json is generated by `pnpm --filter pipeline
 * gazetteer` and committed, so builds are deterministic and do not depend on
 * census.gov being up.
 */

export interface GazetteerEntry {
  name: string;
  lon: number;
  lat: number;
  /** Land area in square meters; drives how widely approximate points spread. */
  areaM2: number;
}

export interface Gazetteer {
  places: Record<string, GazetteerEntry>;
  counties: Record<string, GazetteerEntry>;
}

/**
 * Normalize a place or county name so CEQAnet's spelling matches the
 * Census's. Census names carry suffixes ("Redding city", "Alamo CDP",
 * "Shasta County"); CEQAnet usually omits them and sometimes prefixes
 * "City of".
 */
export function normalizePlaceName(name: string): string {
  return name
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '') // strip accents (e.g. "Cañada" -> "Canada")
    .toLowerCase()
    .replace(/\(.*?\)/g, ' ')
    .replace(/^(city|town|county) of\s+/, '')
    .replace(/\s+(city|town|cdp|county)$/, '')
    .replace(/\bst\.?\s/g, 'saint ')
    .replace(/\bmt\.?\s/g, 'mount ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/**
 * Parse a Census Gazetteer text file. Older vintages are tab-delimited and
 * newer ones pipe-delimited, and the last header often has trailing spaces,
 * so we detect the delimiter and trim headers.
 */
export function parseGazetteerFile(text: string, stateFips = '06'): GazetteerEntry[] {
  const lines = text.split(/\r?\n/).filter((l) => l.trim() !== '');
  const delimiter = lines[0].includes('|') ? '|' : '\t';
  const header = lines[0].split(delimiter).map((h) => h.trim().toUpperCase());
  const col = (name: string) => {
    const i = header.indexOf(name);
    if (i < 0) throw new Error(`Gazetteer file missing column ${name}`);
    return i;
  };
  const iName = col('NAME');
  const iLat = col('INTPTLAT');
  const iLon = col('INTPTLONG');
  const iLand = col('ALAND');
  const iGeoid = col('GEOID');
  const out: GazetteerEntry[] = [];
  for (const line of lines.slice(1)) {
    const f = line.split(delimiter).map((s) => s.trim());
    if (!f[iGeoid]?.startsWith(stateFips)) continue;
    const lat = Number(f[iLat]);
    const lon = Number(f[iLon]);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;
    out.push({ name: f[iName], lon, lat, areaM2: Number(f[iLand]) || 0 });
  }
  return out;
}

export function buildGazetteer(places: GazetteerEntry[], counties: GazetteerEntry[]): Gazetteer {
  const index = (entries: GazetteerEntry[]) => {
    const out: Record<string, GazetteerEntry> = {};
    // Prefer incorporated places over CDPs when names collide after normalizing.
    const sorted = [...entries].sort((a, b) => Number(/ CDP$/.test(a.name)) - Number(/ CDP$/.test(b.name)));
    for (const e of sorted) {
      const k = normalizePlaceName(e.name);
      if (k && !(k in out)) out[k] = e;
    }
    return out;
  };
  return { places: index(places), counties: index(counties) };
}
